window.TRIBAL_DATA={movements:[{id:"santhal-hul",name:"Santhal Hul (Santhal Rebellion)",years:"1855–1856",startYear:1855,endYear:1856,region:"Rajmahal Hills, Bengal Presidency (present-day Jharkhand)",tribe:"Santhal",location:{name:"Bhognadih, Sahibganj",lat:24.9,lng:87.65},leaders:["Sidhu Murmu","Kanhu Murmu","Chand Murmu","Bhairav Murmu","Phulo Murmu","Jhano Murmu"],causes:["Exploitation by zamindars, moneylenders (mahajans) and revenue officials","Land alienation as Santhal farmland passed to non-tribal landlords","Corrupt police and courts that offered tribals no real recourse"],summary:"Tens of thousands of Santhals under the Murmu brothers declared independence from Company rule, attacked landlords' and moneylenders' establishments, and fought a large colonial military response before being crushed.",outcome:"Suppressed by 1856 with heavy loss of life; led the colonial government to carve out the Santhal Parganas as a separate administrative unit with distinct tenancy protections.",relatedPage:{label:"Santhal Hul Explorer",url:"../santhal-hul-explorer/index.html"},sources:[{label:"National Archives of India",url:"https://nationalarchives.gov.in/"}]},{id:"munda-ulgulan",name:"Munda Ulgulan (Great Tumult)",years:"1899–1900",startYear:1899,endYear:1900,region:"Chotanagpur Plateau, Bengal Presidency (present-day Jharkhand)",tribe:"Munda",location:{name:"Khunti, Chotanagpur",lat:23.08,lng:85.28},leaders:["Birsa Munda"],causes:["Erosion of the khuntkatti communal land-holding system by outsiders (dikus) and landlords","Forced labour (begar) demanded by landlords and forest officials","Restrictions on traditional forest use under new forest laws"],summary:"Birsa Munda, revered as a prophet-leader, called for Munda self-rule (Munda Raj) and led an armed uprising against landlords, missionaries and colonial authority centred on Chotanagpur.",outcome:"Birsa was captured and died in jail in 1900; the revolt nonetheless forced the colonial government to pass the Chotanagpur Tenancy Act (1908), restricting transfer of tribal land to non-tribals.",relatedPage:{label:"Munda Ulgulan Explorer",url:"../munda-ulgulan-explorer/index.html"},sources:[{label:"National Archives of India",url:"https://nationalarchives.gov.in/"}]},{id:"rampa-rebellion",name:"Rampa Rebellion",years:"1922–1924",startYear:1922,endYear:1924,region:"Eastern Ghats, Madras Presidency (present-day Andhra Pradesh)",tribe:"Koya and other hill communities of the Godavari Agency tracts",location:{name:"Rampa, East Godavari",lat:17.85,lng:81.9},leaders:["Alluri Sitarama Raju"],causes:["Madras Forest Act, 1882 restricting podu (shifting) cultivation and access to forest produce","Exploitative outside contractors (muttadars) controlling local trade","Loss of traditional forest rights central to hill-tribe livelihoods"],summary:"Alluri Sitarama Raju organised Koya and other hill fighters into a guerrilla force that attacked police stations across the Godavari Agency, combining tribal grievances over forest rights with broader anti-colonial appeal.",outcome:"Raju was captured and executed in 1924; the rebellion remains one of the most significant armed tribal uprisings of the interwar period and inspired later forest-rights movements.",relatedPage:{label:"Rampa Rebellion Explorer",url:"../rampa-rebellion-explorer/index.html"},sources:[{label:"Andhra Pradesh State Archives",url:"https://tsarchives.telangana.gov.in/"}]},{id:"bhil-resistance",name:"Bhil Resistance",years:"1810s–1913 (recurring)",startYear:1818,endYear:1913,region:"Khandesh, Western Ghats and Central India (present-day Maharashtra, Madhya Pradesh, Rajasthan, Gujarat)",tribe:"Bhil",location:{name:"Khandesh region",lat:21,lng:74.7},leaders:["Tantia Bhil","Govind Guru"],causes:["Company annexation of Bhil territory after 1818 and disruption of existing chiefdoms","Heavy revenue demands and famine conditions in the late 19th century","Forced labour and forest restrictions imposed by colonial administration"],summary:"Bhil resistance recurred across decades: early revolts against Company annexation in the 1810s–20s, Tantia Bhil's guerrilla raids on British supply lines in the 1870s–80s, and Govind Guru's Bhagat reform-and-resistance movement culminating in the Mangarh massacre of 1913, where colonial troops killed hundreds of Bhil protestors.",outcome:"The Mangarh gathering was fired upon in November 1913, killing an estimated 1,500 Bhils; the movement nonetheless left a lasting tradition of Bhil political and religious organisation.",relatedPage:{label:"Tantia Bhil Explorer",url:"../tantia-bhil-explorer/index.html"},sources:[{label:"Rajasthan State Archives",url:"https://archives.rajasthan.gov.in/"}]},{id:"koya-resistance",name:"Koya Resistance",years:"1879–1880, 1922–1924",startYear:1879,endYear:1924,region:"Godavari Agency, Madras Presidency (present-day Telangana/Andhra Pradesh)",tribe:"Koya",location:{name:"Bhadrachalam, Godavari Agency",lat:17.67,lng:80.89},leaders:["Tomma Sora","Raja Anantayyar","Alluri Sitarama Raju (1922–24 phase)"],causes:["Madras Forest Act, 1882 curbing podu cultivation and forest access","Exploitation by non-tribal contractors and moneylenders in the Agency tracts","Excise and toddy-tapping restrictions affecting Koya livelihoods"],summary:"Koya communities rose twice against colonial forest and revenue policy in the Godavari Agency: an 1879–80 uprising led by local Koya chiefs, and participation alongside other hill tribes in the 1922–24 Rampa Rebellion under Alluri Sitarama Raju.",outcome:"Both phases were militarily suppressed, but repeated Koya resistance kept pressure on the colonial government's forest policy in the Agency tracts.",relatedPage:null,sources:[{label:"Andhra Pradesh State Archives",url:"https://tsarchives.telangana.gov.in/"}]},{id:"tana-bhagat",name:"Tana Bhagat Movement",years:"1914–1920s",startYear:1914,endYear:1929,region:"Chotanagpur Plateau, Bengal Presidency (present-day Jharkhand)",tribe:"Oraon (Kurukh)",location:{name:"Gumla, Chotanagpur",lat:23.05,lng:84.55},leaders:["Jatra Bhagat","Turia Bhagat"],causes:["Continued land alienation to non-tribal landlords in the wake of the Munda Ulgulan","Rent and revenue burdens on Oraon cultivators","A wider search for religious and social reform within the community"],summary:"Beginning as a religious reform movement urging Oraons to give up alcohol, animal sacrifice and beggar labour, the Tana Bhagats increasingly linked spiritual purification to opposition to colonial rent demands and forced labour, later aligning with Gandhi's non-cooperation movement.",outcome:"The movement fed into the wider non-cooperation campaign of the 1920s; some Tana Bhagats refused to pay rent or taxes, and the tradition of Gandhian-aligned Oraon activism continued into the 1930s and 40s.",relatedPage:null,sources:[{label:"National Archives of India",url:"https://nationalarchives.gov.in/"}]},{id:"rani-gaidinliu",name:"Rani Gaidinliu's Movement (Heraka / Zeliangrong)",years:"1929–1932 (active resistance)",startYear:1929,endYear:1932,region:"North Cachar Hills and Naga Hills, Assam (present-day Manipur, Nagaland, Assam)",tribe:"Zeliangrong Naga (Rongmei, Zeme, Liangmai)",location:{name:"North Cachar Hills, Assam",lat:25.3,lng:93.3},leaders:["Rani Gaidinliu","Haipou Jadonang"],causes:["Opposition to colonial administration's interference in Zeliangrong religious and political life","Heavy taxation and forced labour demands on hill villages","Suppression of the Heraka religious reform movement founded by Jadonang"],summary:"After Haipou Jadonang's execution by the colonial government in 1931, Gaidinliu, still a teenager, led the Heraka spiritual-political movement calling for Zeliangrong self-rule and refusal of colonial taxes, evading capture for over a year across the hills.",outcome:"Captured in 1932 and imprisoned for 14 years without trial; Jawaharlal Nehru gave her the title 'Rani' (Queen) on her release in 1947 in recognition of her resistance.",relatedPage:{label:"Rani Gaidinliu Explorer",url:"../rani-gaidinliu/rani-gaidinliu.html"},sources:[{label:"Sahapedia — Rani Gaidinliu",url:"https://www.sahapedia.org/"}]},{id:"kol-uprising",name:"Kol Uprising",years:"1831–1832",startYear:1831,endYear:1832,region:"Chotanagpur Plateau, Bengal Presidency (present-day Jharkhand)",tribe:"Kol (Ho, Munda, Oraon)",location:{name:"Singhbhum, Chotanagpur",lat:22.8,lng:85.98},leaders:["Buddho Bhagat","Joa Bhagat"],causes:["Transfer of tribal land to outsider landlords and Sikh and Muslim farm managers (thikadars)","Erosion of traditional Kol land tenure under Company revenue policy","Oppressive rent collection by absentee landlords"],summary:"Kol cultivators rose against landlords and revenue officials across Chotanagpur, destroying property associated with outside control of tribal land before Company troops suppressed the uprising.",outcome:"Suppressed within a year; contributed to early colonial recognition that tribal land tenure needed separate legal treatment, a precedent later expanded after the Munda Ulgulan.",relatedPage:null,sources:[{label:"National Archives of India",url:"https://nationalarchives.gov.in/"}]},{id:"bastar-rebellion",name:"Bastar Rebellion (Bhumkal)",years:"1910",startYear:1910,endYear:1910,region:"Bastar State, Central Provinces (present-day Chhattisgarh)",tribe:"Gond and Muria",location:{name:"Bastar",lat:19.25,lng:81.96},leaders:["Gunda Dhur"],causes:["Reservation of forest land for timber extraction, cutting Gond and Muria communities off from customary forest use","New taxes and forced labour demands imposed by the Bastar administration","Resentment at outside contractors and officials managing forest resources"],summary:"Known locally as Bhumkal ('earthquake'), the uprising saw Gond and Muria villagers under Gunda Dhur attack administrative outposts and burn forest department records across Bastar State in protest at forest reservation policy.",outcome:"Suppressed by colonial and state forces within months, but forced a partial rollback of forest reservation in Bastar and remains a reference point in later forest-rights movements in the region.",relatedPage:null,sources:[{label:"Chhattisgarh State Archives",url:"https://archives.cg.gov.in/"}]}],causesTaxonomy:[{id:"land",label:"Land alienation",description:"Transfer of tribal land to non-tribal landlords, moneylenders or outside settlers."},{id:"forest",label:"Forest restrictions",description:"Colonial forest laws cutting off access to shifting cultivation, grazing and forest produce."},{id:"labour",label:"Forced labour",description:"Unpaid or underpaid labour (begar) demanded by landlords, contractors or officials."},{id:"revenue",label:"Revenue & taxation",description:"New or increased revenue and tax demands unfamiliar to tribal economies."},{id:"religious",label:"Religious/cultural suppression",description:"Interference with tribal religious practice or reform movements."}]};